using System.Globalization;
using System.Text.Json.Nodes;

namespace OurNotes.Director.Core;

/// <summary>Audio-only execution for explicitly timed, locally voiced shots. The same
/// player, PCM mixer, external resource resolver and speaker ownership are used by the
/// graphical renderer. Unsupported movie/game-audio semantics use the full interpreter.</summary>
public sealed class ExternalVoiceTimeline
{
    static readonly HashSet<string> VisualOnly = new(StringComparer.Ordinal)
    {
        "Character", "Motion", "MotionLoop", "Expression", "Delay", "Pause", "Resume", "EyeBlink",
        "In", "Out", "Costume", "Director.Actor", "Director.Camera", "Director.Parameter", "Director.Scene"
    };
    public static bool Supports(JsonNode document)
    {
        if(document["initialize"] is not JsonArray {Count:0} || document["finalize"] is not JsonArray {Count:0}
            || document["commands"] is not JsonArray rows) return false;
        foreach(var item in rows)
        {
            if(item is not JsonObject row || row["AtFrame"] is not JsonValue value || !value.TryGetValue<int>(out _))return false;
            var command=AdvProgram.Row(row,"audio eligibility");if(command.Ignored)continue;
            if(VisualOnly.Contains(command.Command))continue;
            if(command.Command!="Voice" || string.IsNullOrWhiteSpace(command.Text("AudioPath")))return false;
        }
        // The scene player's letterbox preparation would add a source-dependent wait.
        return document["output"]?["letterbox"]?.ToString()=="none" && document["output"]?["playbackViewport"] is null;
    }
    public AdvLoop Loop {get;} = new();
    public AdvAudio Audio {get;}
    public AdvPlayback Player {get;}
    readonly ExternalVoiceBank files;
    readonly VoiceTrackPlayback voices;
    public ExternalVoiceTimeline(JsonNode document,string baseDirectory,string ffmpeg)
    {
        if(!Supports(document))throw new ArgumentException("This scene requires the complete audio interpreter.");
        var rows=document["commands"]!.AsArray().Select((row,index)=>AdvProgram.Row(row!,index.ToString(CultureInfo.InvariantCulture))).ToArray();
        Audio=new(Loop,[]);files=new(Audio,baseDirectory,ffmpeg);voices=new(Audio);
        Player=new(Loop,new AdvProgram{Rows=rows}){Prepare=_=>[]};Audio.Bind(Player);
        Player.Register("TalkWindow",(_,_)=>[]);
        foreach(string command in rows.Where(row=>!row.Ignored).Select(row=>row.Command).Distinct())
        {
            if(command=="Voice")Player.Register(command,PlayVoice);
            else if(command!="Delay")Player.Register(command,(_,_)=>[]);
        }
        Player.Start();
    }
    IEnumerable<AdvWait> PlayVoice(AdvRow row,AdvPlayback player)
    {
        row=files.Resolve(row);
        var names=row.Text("TargetName").Split(',',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries);
        var ids=row.Data["VoiceIDs"]!.AsArray().Select(id=>long.Parse(id!.ToString(),CultureInfo.InvariantCulture)).ToArray();
        var sounds=voices.Start(names,ids,row.Index);
        while(!player.Cancelled&&sounds.Any(s=>Audio.IsPlaying(s.Id)))yield return Loop.YieldUpdate();
    }
    public void MixFrame(Span<float> output) {Loop.Drain();Player.ThrowIfFailed();Audio.MixFrame(output);}
    public void Step()=>Player.Step();
}

void ProduceTimedVoices(ScenePreviewSource source,JsonNode document)
{
    var timeline=new ExternalVoiceTimeline(document,Path.GetDirectoryName(Path.GetFullPath(source.ProjectPath))!,source.FfmpegPath);
    var mix=new float[AdvAudio.SamplesPerFrame*2];var pcm=new byte[mix.Length*sizeof(short)];
    int limit=source.DurationMode==PreviewDurationMode.Automatic?30*36000:checked((int)Math.Ceiling(source.Duration*30));
    for(int frame=0;frame<limit;frame++)
    {
        cancellation.Token.ThrowIfCancellationRequested();
        while(AvailableSamples>=Interlocked.Read(ref requested)){demand.WaitOne(100);cancellation.Token.ThrowIfCancellationRequested();}
        timeline.MixFrame(mix);ToPcm16(mix,pcm);RandomAccess.Write(file,pcm,(long)frame*pcm.Length);
        Interlocked.Add(ref available,AdvAudio.SamplesPerFrame);
        if(source.DurationMode==PreviewDurationMode.Automatic&&timeline.Player.Finished)break;
        timeline.Step();
    }
}

using System.Text.Json.Nodes;

namespace OurNotes.Director.Core;

/// <summary>Output-layer selection. It is a drawing option, never a command that resets
/// the original stage (and therefore its camera, actor slots, timing or light setup).</summary>
public static class SceneContent
{
    public static string Read(JsonNode? value)
    {
        if(value is null)return "scene";
        if(value is JsonValue json && json.TryGetValue<string>(out var content) && content is "scene" or "characters")return content;
        throw new ArgumentException("画面内容必须是 scene（完整场景）或 characters（仅人物透明）。");
    }
}

public sealed partial class AdvUi
{
    public string AudioProjectDirectory { get; set; } = Environment.CurrentDirectory;
    public string AudioFfmpegPath { get; set; } = "ffmpeg";
    ExternalVoiceBank? externalVoiceBank;
    AdvRow ResolveExternalVoice(AdvRow row) => (externalVoiceBank ??= new(audio, AudioProjectDirectory, AudioFfmpegPath)).Resolve(row);
}

namespace OurNotes.Director.Core;

/// <summary>Owns scheduled voices by speaker, not by the last instruction globally.
/// Multiple speakers/narration can overlap. Replacing a speaker stops only that speaker's
/// preceding take; cleanup from an older take cannot detach a newer mouth driver.</summary>
public sealed class VoiceTrackPlayback(AdvAudio audio)
{
    readonly Dictionary<string, AdvSound[]> owners = new(StringComparer.Ordinal);

    public AdvSound[] Start(string[] speakers, long[] cueIds, string narrationId,
        Action<string, AdvSound>? attachLipSync = null)
    {
        ArgumentNullException.ThrowIfNull(speakers);
        ArgumentNullException.ThrowIfNull(cueIds);
        var keys = speakers.Where(s => !string.IsNullOrWhiteSpace(s)).Distinct(StringComparer.Ordinal).ToArray();
        if (keys.Length == 0) keys = ["\0narration:" + narrationId];
        // Resolve every cue before replacing an existing voice. A missing resource must
        // not silence an unrelated, already-playing take.
        foreach (long id in cueIds) audio.GetCue(id);
        foreach (string key in keys)
            if (owners.Remove(key, out var previous))
                foreach (var voice in previous) audio.Stop(voice.Id);
        var started = cueIds.Select(id => audio.Play(id)).ToArray();
        if (started.Length == 0) return started;
        foreach (string key in keys) owners[key] = started;
        for (int i = 0; i < speakers.Length; i++)
            if (!string.IsNullOrWhiteSpace(speakers[i])) attachLipSync?.Invoke(speakers[i], started[Math.Min(i, started.Length - 1)]);
        foreach (var sound in started) sound.OnFinished.Add(() =>
        {
            if (started.Any(s => audio.IsPlaying(s.Id))) return;
            foreach (string key in keys)
                if (owners.TryGetValue(key, out var current) && ReferenceEquals(current, started)) owners.Remove(key);
        });
        return started;
    }
}
